      'helpBothBody': 'अपनी आवाज़ रिकॉर्ड करें, लक्षित भाषा चुनें, और एक चरण में मूल ट्रांसक्रिप्शन और उसका अनुवाद प्राप्त करें।',
      'helpFullCycleBody': 'पूर्ण वॉयस पाइपलाइन: आवाज़ रिकॉर्ड करें → ट्रांसक्राइब करें → अनुवाद करें → लक्षित भाषा में ऑडियो बनाएं। आवाज़-से-आवाज़ अनुवाद के लिए आदर्श।',
