      'helpAboutTitle': 'აპლიკაციის შესახებ',
      'helpAboutBody': 'Voice Translator AI იყენებს OpenAI API-ს მეტყველების ტრანსკრიფციისთვის, თარგმნისთვის და სინთეზისთვის. აპლიკაციის გამოყენებამდე დაამატეთ თქვენი API გასაღები პარამეტრებში. გასაღები ინახება მხოლოდ თქვენს მოწყობილობაზე.',
